SELECT

FROM builtin_skills
WHERE deleted_at IS NULL AND listed AND latest_version IS NOT NULL
ORDER BY created_at DESC, id DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT

FROM builtin_skill_versions
WHERE skill_uuid = #{skillUUID}
AND state = 'published'
AND deleted_at IS NULL
ORDER BY created_at ASC, id ASCcreated_at DESC, id DESC
LIMIT #{limit}
OFFSET #{offset}
